import { WILDCARD_GROUP, checkGroupAccess, isPageGroups } from '../../../navigation/groupAccess.js';
import { isObject } from '../../../types/guards.js';
const trimGroupNames = (names) => [...new Set(names.map((name) => name.trim()))];
const isGroupNames = (groups) => groups.every((entry) => typeof entry === 'string');
export const toPageGroups = (groups) => Array.isArray(groups) ? groups : [groups];
export function toVisibilityGroups(value) {
    if (Array.isArray(value)) {
        if (value.length === 0 || !isPageGroups(value) || !isGroupNames(value))
            return undefined;
        const names = trimGroupNames(value);
        return isPageGroups(names) ? names : undefined;
    }
    const rules = [value];
    if (!isPageGroups(rules) || isGroupNames(rules))
        return undefined;
    const [rule] = rules.map(({ includes, excludes }) => (Object.assign(Object.assign({}, (includes && { includes: trimGroupNames(includes) })), (excludes && { excludes: trimGroupNames(excludes) }))));
    return rule && isPageGroups([rule]) ? rule : undefined;
}
export function toVisibilityGroupsRule(value) {
    if (!isObject(value) || Object.keys(value).length !== 1)
        return undefined;
    const groups = toVisibilityGroups(value.groups);
    return groups && { groups };
}
export function matchesVisibilityAuthRule(rule, viewer) {
    if (rule === 'signed-in')
        return viewer.signedIn;
    if (rule === 'signed-out')
        return !viewer.signedIn;
    return checkGroupAccess(toPageGroups(rule.groups), new Set(viewer.signedIn ? [...viewer.groups, WILDCARD_GROUP] : []));
}
